# ---------------------------------------------------------------------------
# Online merge and split of independent metric log sets
#
# :func:`merge_metrics` gathers several whole log sets, in the caller's
# deterministic order, into one of them (the first path); :func:`split_metrics`
# moves every surviving record of one log set into caller-named sets at
# record-ordinal boundaries.  Records move byte for byte with their original
# newlines; torn tails and blank lines keep the read-time rule.  Every
# record's ordinal mapping is deterministic: the reorganisation plan carries
# one linear old-to-new ordinal translation per participating log.
#
# Both operations take every involved log's lock one at a time in
# lexicographic path order -- never two at once out of order -- exactly the
# way a cross-log transaction does, so concurrent appends, commits,
# rollbacks, adjudications and replays serialise instead of deadlocking.
# All output content is staged first (data slices, moved snapshot copies,
# rebuilt consumer-group files, translated transaction state); only then is
# the plan published as the commit point.
#
# Crash states, all settled from :func:`_finish_pending` under the log's own
# lock:
#
# * no plan marker -- staging files are orphans a dead run left and are
#   swept from each involved path;
# * a freeze marker (``path.reorgfreeze``) with no committed plan on any
#   involved path -- the run died at or before the commit point; the few
# * a plan marker on at least one involved path (``path.reorg``) -- the
#   commit point was crossed; every involved path finishes only its own,
#   strictly local, idempotent finalisation, so no finaliser needs another
#   log's lock.
#
# Transaction state is translated to the new ordinals and owner logs as part
# of the plan: decided transactions keep their verdict, still-undecided
# transactions keep their identifier order and batches, and write serials,
# commit points and replay output reconcile record by record.  Per-log
# participant indexes (``path.txidx``) keep every later transaction read
# scoped to the logs it touches.
# ---------------------------------------------------------------------------

_REORG_VERSION = 1
_REORG_PLAN_SUFFIX = ".reorg"
_REORG_FREEZE_SUFFIX = ".reorgfreeze"
_REORG_SEG_SUFFIX = ".reorgseg"
_REORG_SEG_TMP_SUFFIX = ".reorgseg.tmp"
_REORG_SNAP_SUFFIX = ".reorgsnap."
_REORG_SNAP_TMP_SUFFIX = ".reorgsnap.tmp."
_REORG_GROUP_SUFFIX = ".reorggroup."
_REORG_GROUP_TMP_SUFFIX = ".reorggroup.tmp."
_REORG_LOCK_SUFFIX = ".reorglock"


def _reorg_plan_path(path):
    return path + _REORG_PLAN_SUFFIX


def _reorg_freeze_path(path):
    return path + _REORG_FREEZE_SUFFIX


def _reorg_lock_path(path):
    return path + _REORG_LOCK_SUFFIX


def _reorg_read_json(path):
    """Read one reorg marker document, naming the file on corruption."""
    fd = os.open(path, os.O_RDONLY)
    try:
        raw = b""
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            raw += chunk
    finally:
        os.close(fd)
    try:
        return json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise ValueError(f"corrupt reorg state {path!r}: {exc}") from exc


def _reorg_publish(tmp, target, state):
    payload = json.dumps(state, separators=(",", ":")).encode("utf-8")
    _tx_publish_json(tmp, target, payload)


def _reorg_stage_bytes(tmp, target, chunks):
    """Stream ``chunks`` (bytes iterable) to ``tmp``, fsync, rename."""
    out = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    try:
        for chunk in chunks:
            _write_bytes(out, chunk)
        os.fsync(out)
    finally:
        os.close(out)
    os.replace(tmp, target)


def _reorg_stream_file(src):
    """Yield fixed-size byte chunks of one file for a streaming copy."""
    fd = os.open(src, os.O_RDONLY)
    try:
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            yield chunk
    finally:
        os.close(fd)


def _reorg_stream_records(src):
    """Yield each complete record's bytes (newline attached) from one file."""
    yield from _iter_raw_records(src)


def _reorg_collect(path):
    """Settled ``(members, pruned, total)`` for one involved log."""
    members = _segment_members(path)
    pruned = _read_prune_state(path)[0]
    surviving = 0
    for member in members:
        surviving += sum(1 for _ in _iter_raw_records(member))
    return members, pruned, pruned + surviving


def _reorg_anchor(plan_paths):
    """The never-renamed flock anchor for one reorganisation.

    It serialises crash cleanup of a plan that died at the commit point;
    the anchor is left in place afterwards, the way group-state lock
    anchors are, so a held lock never names a file another process unlinks.
    """
    anchor = _reorg_lock_path(min(plan_paths))
    fd = os.open(anchor, os.O_RDWR | os.O_CREAT, 0o666)
    try:
        if fcntl is not None:
            fcntl.flock(fd, fcntl.LOCK_EX)
    except OSError:
        os.close(fd)
        raise
    return fd


def _reorg_sweep_orphans(path):
    """Remove staging files a dead reorg left with no plan marker.

    Only the reorg-private prefixes are touched, never data members or
    established sidecars; safe to call under the log lock whenever no
    freeze or committed plan exists for ``path``.
    """
    directory = os.path.dirname(path) or "."
    base = os.path.basename(path)
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return
    for name in names:
        if (
            name == base + _REORG_SEG_SUFFIX
            or name.startswith(base + _REORG_SNAP_SUFFIX)
            or name.startswith(base + _REORG_SNAP_TMP_SUFFIX)
            or name.startswith(base + _REORG_GROUP_SUFFIX)
            or name.startswith(base + _REORG_GROUP_TMP_SUFFIX)
        ):
            _unlink_if_exists(os.path.join(directory, name))
    _unlink_if_exists(path + _REORG_SEG_TMP_SUFFIX)


def _reorg_list_groups(path):
    """Return ``{group: state_path}`` currently published on one log."""
    directory = os.path.dirname(path) or "."
    base = os.path.basename(path)
    prefix = base + _GROUP_STATE_SUFFIX
    groups = {}
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return groups
    for name in names:
        if name.startswith(prefix):
            group = name[len(prefix):]
            # Lock and tmp anchors are never group state.
            if group.endswith(_GROUP_STATE_LOCK_SUFFIX) or group.endswith(
                _GROUP_STATE_TMP_SUFFIX
            ):
                continue
            groups[group] = os.path.join(directory, name)
    return groups


def _reorg_prune_point(pruned, ordinal, base, start):
    """Translate one source ordinal into a moved consumer-group position.

    Positions inside the source's pruned region clamp to the first
    surviving record's new ordinal, matching the established read rule.
    """
    if ordinal <= pruned:
        return base
    return base + (ordinal - start)


# -- transaction coordinator rewriting -------------------------------------

def _reorg_involved_ids(absolute):
    """Every transaction id still recorded against the involved logs.

    The per-log participant index is the narrow scope when present; an old
    segment set without one falls back to scanning the registry directory,
    exactly the records a first index build would include.
    """
    ids = set()
    indexed = False
    for abspath in absolute:
        index = _tx_read_index(abspath)
        if index is None:
            indexed = False
            break
        ids.update(index)
        indexed = True
    if indexed:
        return ids
    wanted = set(absolute)
    return {
        record["id"]
        for record in _tx_registry_records()
        if not wanted.isdisjoint(record["logs"])
    }


class _ReorgMapping:
    """Ordinal map from old log ordinals to ``(owner, new ordinal)``.

    ``point`` maps any boundary ordinal (including an empty batch's serial)
    deterministically; records map through the same linear pieces, so every
    target record's new ordinal is uniquely computable before or after the
    move.
    """

    def __init__(self, kind, involved, pieces):
        self.kind = kind
        self.involved = involved
        # pieces: merge  [(src, pruned, total, base)] all owned by target
        #          split  [(start, end, owner)] over the one source
        self.pieces = pieces

    @classmethod
    def merge(cls, sources, target, bases):
        pieces = [
            (src, pruned, total, base)
            for (src, pruned, total), base in zip(
                [(s[0], s[1], s[2]) for s in sources], bases
            )
        ]
        return cls("merge", set(sources), pieces) | None if False else cls(
            "merge", {s[0] for s in sources}, pieces
        )

    def point(self, log, ordinal):
        if self.kind == "merge":
            for src, pruned, total, base in self.pieces:
                if log == src:
                    if ordinal < pruned:
                        ordinal = pruned
                    if ordinal > total:
                        ordinal = total
                    return self.pieces[0] and (
                        self._merge_target(), base + (ordinal - pruned)
                    ) if False else (self._merge_target(),
                                    base + (ordinal - pruned))
            raise KeyError(log)
        start, end, owner = self._split_piece_for(ordinal)
        return owner, max(0, ordinal - start)

    def _merge_target(self):
        return self.pieces[0][3] is not None and self._target

    def record_owner(self, log, ordinal):
        if self.kind == "merge":
            return self._target
        return self._split_piece_for(ordinal)[2]

    def _split_piece_for(self, ordinal):
        chosen = self.pieces[0]
        for piece in self.pieces:
            start, end, _owner = piece
            if start <= ordinal < end:
                return piece
            if start <= ordinal:
                chosen = piece
        return chosen

    def with_target(self, target):
        self._target = target
        return self
