# ---------------------------------------------------------------------------
# Online merge and split of independent metric log sets
#
# merge_metrics gathers several whole log sets, in the caller's deterministic
# order (destination first, then each source), into the destination set;
# split_metrics moves every surviving record of one set into caller-named
# sets at boundaries that must each land on a whole-record edge.  Records
# move byte for byte with their original newlines; the torn tail and blank
# lines keep the established read rule.  Every moved record's new ordinal is
# uniquely computable: merge lays the sets' surviving records out one after
# another, each set starting at the running record count; split lays the
# slices out in destination order, the new ordinals starting at zero with
# the pruned basis rebuilt.
#
# Every involved log is guarded (the reentrant same-process guard) and
# flock-locked one at a time in lexicographic absolute-path order and held
# until the commit finishes, the same acyclic acquisition cross-log
# transactions use; concurrent appends, commits, rollbacks, adjudications
# and replays therefore serialise instead of deadlocking.  Content is
# staged first; the commit point arms a plan marker (``path.reorg``) on
# every involved path and replaces the affected transaction coordinator
# records; only afterwards does each path swap its own whole slice in as
# its sole segment.  All per-path finalisation is local and idempotent, so a
# crash leaves either the old layout or a deterministically finished one and
# never a mixture:
#
# * no plan marker -- staging files are orphans of a run that died before
#   the commit point and are swept by the next writer on that path;
# * a plan marker -- the run crossed the commit point; the next writer
#   finishes it (arm any peer markers, replace coordinator records from
#   their staged payloads, swap the local slice and private state) under an
#   anchor flock a dead run already released.
#
# Decided transactions keep their verdict with write serials and
# participating logs translated to the moved records; still-open
# transactions keep their identifier order and staged batches, split across
# the new owners record by record; a transaction still mid-preparation is
# left on its declared paths, exactly like any other concurrent writer.
# Snapshot handles are rebuilt against the new sequence they now pin,
# consumer-group positions move by the same ordinal map, and the audit chain
# is rebuilt on every set that had one.
# ---------------------------------------------------------------------------

_REORG_VERSION = 1
_REORG_PLAN_SUFFIX = ".reorg"
_REORG_FREEZE_SUFFIX = ".reorgfreeze"
_REORG_LOCK_SUFFIX = ".reorglock"
_REORG_SEG_SUFFIX = ".reorgseg"
_REORG_SEG_TMP = _REORG_SEG_SUFFIX + ".tmp"
_REORG_SNAP_PREFIX = ".reorgsnap."
_REORG_SNAP_REGISTRY_STAGED = ".reorg.snapshots"
_REORG_GROUP_PREFIX = ".reorggroup."
_REORG_TX_SIDECAR_STAGED = ".reorg.tx"
_REORG_TXINDEX_STAGED = ".reorg.txidx"
_REORG_TXSTAGE_PREFIX = ".reorgtxstage."
_REORG_COORD_TMP_SUFFIX = ".json.reorgtmp"

# Reentrant same-process guards for the anchor flock, mirroring the
# transaction guards so same-process recovery never self-deadlocks.
_reorg_anchor_guards = {}
_reorg_anchor_guard_refs = {}


# -- per-log transaction participant index ---------------------------------
#
# ``path.txidx`` is one JSON array of exact decimal transaction identifiers
# that ever participated in the log, append-only and published atomically.
# It scopes every read of the global coordinator registry to transactions
# related to the log in hand, so an unrelated corrupt record never disturbs
# an operation; an old segment set without the file falls back to the
# registry scan and gets the index built on its next transaction or
# reorganisation.

_TX_INDEX_SUFFIX = ".txidx"
_TX_INDEX_TMP_SUFFIX = ".txidx.tmp"


def _tx_index_path(path):
    return path + _TX_INDEX_SUFFIX


def _tx_read_index(path):
    """Return the sorted participant-id index, or ``None`` when absent."""
    try:
        fd = os.open(_tx_index_path(path), os.O_RDONLY)
    except FileNotFoundError:
        return None
    try:
        raw = b""
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            raw += chunk
    finally:
        os.close(fd)
    try:
        ids = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise ValueError(
            f"corrupt transaction index {_tx_index_path(path)!r}: {exc}"
        ) from exc
    if not isinstance(ids, list) or any(
        isinstance(txid, bool) or not isinstance(txid, int) or txid < 0
        for txid in ids
    ):
        raise ValueError(
            f"corrupt transaction index {_tx_index_path(path)!r}: "
            f"index must be a list of transaction ids"
        )
    return sorted(ids)


def _tx_write_index(path, ids):
    """Atomically publish the participant index; an empty one is removed."""
    tmp = path + _TX_INDEX_TMP_SUFFIX
    if not ids:
        _unlink_if_exists(tmp)
        _unlink_if_exists(_tx_index_path(path))
        return
    payload = json.dumps(sorted(set(ids)), separators=(",", ":")).encode(
        "utf-8"
    )
    _tx_publish_json(tmp, _tx_index_path(path), payload)


def _tx_index_add(path, txid):
    """Append one identifier to a log's participant index (lock held)."""
    ids = _tx_read_index(path)
    if ids is None:
        ids = []
    if txid not in ids:
        _tx_write_index(path, ids + [txid])


def _tx_related_ids(abspaths):
    """Union of transaction ids related to the given logs.

    Uses the narrow per-log indexes whenever every log has one; a single
    missing index falls back to scanning the coordinator registry for
    transactions participating in any of the logs, exactly the records an
    index build would register.
    """
    union = set()
    indexed = True
    for abspath in abspaths:
        ids = _tx_read_index(abspath)
        if ids is None:
            indexed = False
            break
        union.update(ids)
    if indexed:
        return union
    wanted = set(abspaths)
    return {
        record["id"]
        for record in _tx_registry_records()
        if not wanted.isdisjoint(record["logs"])
    }


# -- markers and locks ------------------------------------------------------

def _reorg_plan_path(path):
    return path + _REORG_PLAN_SUFFIX


def _reorg_freeze_path(path):
    return path + _REORG_FREEZE_SUFFIX


def _reorg_lock_path(abspath):
    return abspath + _REORG_LOCK_SUFFIX


def _reorg_anchor_guard(anchor):
    return _TxGuard(_reorg_anchor_guards, _reorg_anchor_guard_refs, anchor)


def _reorg_read_plan(path):
    """Read a committed reorg plan marker; ``None`` when it is absent."""
    try:
        fd = os.open(_reorg_plan_path(path), os.O_RDONLY)
    except FileNotFoundError:
        return None
    try:
        raw = b""
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            raw += chunk
    finally:
        os.close(fd)
    try:
        return json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise ValueError(
            f"corrupt reorg state {_reorg_plan_path(path)!r}: {exc}"
        ) from exc


def _reorg_publish_file(target, payload):
    _tx_publish_json(target + ".tmp", target, payload)


def _reorg_anchor_flock(anchor):
    """Take the anchor flock serialising reorg recovery (fd or None)."""
    if fcntl is None:
        return None
    fd = os.open(anchor, os.O_RDWR | os.O_CREAT, 0o666)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
    except OSError:
        os.close(fd)
        raise
    return fd


def _reorg_sweep_path_orphans(path):
    """Remove every private reorg staging file a dead run left on ``path``.

    Data members and established sidecars use other names; only the
    reorg-private prefixes are touched.
    """
    directory = os.path.dirname(path) or "."
    base = os.path.basename(path)
    prefixes = (
        _REORG_SEG_PREFIX_DUMMY := "",  # replaced below
    )
    del prefixes
    prefixes = (
        _REORG_SNAP_PREFIX,
        _REORG_GROUP_PREFIX,
        _REORG_TXSTAGE_PREFIX,
    )
    exact = (
        _REORG_SEG_SUFFIX,
        _REORG_SEG_TMP,
        _REORG_SNAP_REGISTRY_STAGED,
        _REORG_TX_SIDECAR_STAGED,
        _REORG_TXINDEX_STAGED,
        _REORG_PLAN_SUFFIX,
        _REORG_FREEZE_SUFFIX,
    )
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return
    for name in names:
        if name in (base + suffix for suffix in exact) or any(
            name.startswith(base + prefix) for prefix in prefixes
        ):
            _unlink_if_exists(os.path.join(directory, name))


def _reorg_sweep_coord_temps():
    """Remove staged coordinator payloads of a run that never committed."""
    directory = _tx_registry_dir()
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return
    for name in names:
        if name.endswith(_REORG_COORD_TMP_SUFFIX):
            _unlink_if_exists(os.path.join(directory, name))


def _reorg_list_old_groups(path):
    """``{group: state_path}`` of consumer-group state files on one log."""
    directory = os.path.dirname(path) or "."
    base = os.path.basename(path)
    prefix = base + _GROUP_STATE_SUFFIX
    groups = {}
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return groups
    for name in names:
        if not name.startswith(prefix):
            continue
        group = name[len(prefix):]
        if group.endswith(_GROUP_STATE_LOCK_SUFFIX) or group.endswith(
            _GROUP_STATE_TMP_SUFFIX
        ):
            continue
        groups[group] = os.path.join(directory, name)
    return groups


def _reorg_point_owner(points, local):
    """Owner of local ordinal ``local`` over ``[(start, owner)]``.

    A boundary equal to a slice start belongs to the slice starting there;
    an ordinal past every start belongs to the last slice.
    """
    owner = points[-1][1]
    for start, candidate in points:
        if local < start:
            return owner
        owner = candidate
    return owner


# -- validation -------------------------------------------------------------

def _reorg_check_str_path(path):
    if not isinstance(path, str):
        raise OSError(
            f"log path must be a string, got {type(path).__name__}"
        )
    if os.path.isdir(path):
        raise IsADirectoryError(f"log path is a directory: {path!r}")


def _reorg_require_existing(path):
    _reorg_check_str_path(path)
    if not os.path.exists(path) and not _segment_numbers(path):
        raise FileNotFoundError(f"metrics log does not exist: {path!r}")


def _reorg_lock_one(abspath, create):
    """Lock one involved log, creating the live file when ``create`` is set."""
    if create and not os.path.exists(abspath) and not _segment_numbers(abspath):
        guard = _tx_log_guard(abspath)
        guard.__enter__()
        fd = _mutation_lock(abspath, create=True)
        return guard, fd
    guard = _tx_log_guard(abspath)
    guard.__enter__()
    fd = _tx_lock_existing_set(abspath)
    _finish_pending(abspath)
    fd = _relock_after_settle(fd, abspath, create=True)
    return guard, fd


def _reorg_acquire(involved, creates):
    """Guard, lock and settle every involved log in lexicographic order.

    Returns ``[(abspath, guard, fd, create)]``; the caller releases in
    reverse.  ``creates`` is the set of paths allowed to be born.
    """
    held = []
    try:
        for abspath in sorted(involved):
            guard, fd = _reorg_lock_one(abspath, abspath in creates)
            held.append([abspath, guard, fd])
        return held
    except BaseException:
        for _abspath, guard, fd in reversed(held):
            if fd is not None:
                try:
                    os.close(fd)
                except OSError:
                    pass
            guard.__exit__(None, None, None)
        raise


def _reorg_release(held):
    for _abspath, guard, fd in reversed(held):
        if fd is not None:
            os.close(fd)
        guard.__exit__(None, None, None)


# -- streaming staging ------------------------------------------------------

def _reorg_stream_path_records(path):
    """Yield every surviving record's bytes across one set's members."""
    for member in _segment_members(path):
        yield from _iter_raw_records(member)


def _reorg_collect(path):
    """Settled ``(members, pruned, surviving, total)`` for one log."""
    members = _segment_members(path)
    pruned = _read_prune_state(path)[0]
    surviving = 0
    for member in members:
        surviving += sum(1 for _ in _iter_raw_records(member))
    return members, pruned, surviving, pruned + surviving


def _reorg_stage_slice(target, sources):
    """Stream record iterables into ``<target>.reorgseg`` atomically."""
    tmp = target + _REORG_SEG_TMP
    out = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    try:
        for source in sources:
            for raw in source:
                _write_bytes(out, raw)
        os.fsync(out)
    finally:
        os.close(out)
    os.replace(tmp, target + _REORG_SEG_SUFFIX)


def _reorg_copy_file(src, dst, tmp):
    """Stream one file byte for byte to ``tmp``, fsync and rename."""
    out = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    try:
        fd = os.open(src, os.O_RDONLY)
        try:
            while True:
                chunk = os.read(fd, _READ_CHUNK)
                if not chunk:
                    break
                _write_bytes(out, chunk)
        finally:
            os.close(fd)
        os.fsync(out)
    finally:
        os.close(out)
    os.replace(tmp, dst)


def _reorg_slice_window(abspath, start, end):
    """Yield surviving records with local index in ``[start, end)``."""
    index = 0
    for raw in _reorg_stream_path_records(abspath):
        if start <= index < end:
            yield raw
        index += 1


# -- private-state staging and finalisation ---------------------------------

def _reorg_stage_snapshot_state(host, handles, total, slice_path):
    """Stage rebuilt snapshot copies and registry for one new owner."""
    registry = {}
    for handle in handles:
        dst = host + _REORG_SNAP_PREFIX + handle
        tmp = dst + ".tmp"
        if os.path.getsize(slice_path) == 0:
            # An empty pinned sequence needs no copy; create it empty the
            # same way, still fsynced and atomically named.
            _reorg_stage_slice(dst, [])
            os.replace(dst + _REORG_SEG_TMP, dst + ".tmp") if False else None
        _reorg_copy_file(slice_path, dst, tmp)
        registry[handle] = {"pruned": 0, "total": total}
    staged = host + _REORG_SNAP_REGISTRY_STAGED
    if registry:
        payload = json.dumps(registry, separators=(",", ":")).encode("utf-8")
        _tx_publish_json(staged + ".tmp", staged, payload)


def _reorg_group_state_with_position(state_path, position):
    """Read one group state and return it with the position replaced."""
    state = _load_group_state(state_path)
    state["position"] = position
    return state


def _reorg_stage_group(host, group, state):
    dst = host + _REORG_GROUP_PREFIX + group
    payload = json.dumps(state, separators=(",", ":")).encode("utf-8")
    _tx_publish_json(dst + ".tmp", dst, payload)


def _reorg_remove_old_snapshots(path):
    """Delete the live registry and every snapshot private copy."""
    directory = os.path.dirname(path) or "."
    base = os.path.basename(path)
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return
    for name in names:
        if name.startswith(base + _SNAP_COPY_SUFFIX):
            _unlink_if_exists(os.path.join(directory, name))
    _unlink_if_exists(path + _REGISTRY_SUFFIX)
    _unlink_if_exists(path + _REGISTRY_TMP_SUFFIX)


def _reorg_remove_old_tx_state(path, keep_stage_ids):
    """Remove live transaction sidecars/stages the reorg replaces.

    Stages for identifiers the new layout still prepares are renamed into
    place from their staged copies; every other old stage is discarded.
    """
    directory = os.path.dirname(path) or "."
    base = os.path.basename(path)
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        names = []
    for name in names:
        if name.startswith(base + _TX_STAGE_SUFFIX) or name.startswith(
            base + _TX_STAGE_TMP_SUFFIX
        ):
            _unlink_if_exists(os.path.join(directory, name))
    _unlink_if_exists(_tx_sidecar_path(path))
    _unlink_if_exists(path + _TX_SIDECAR_TMP_SUFFIX)
    _unlink_if_exists(_tx_index_path(path))
    _unlink_if_exists(path + _TX_INDEX_TMP_SUFFIX)


def _reorg_local_finalize(abspath, doc):
    """Swap this one path into its new layout from the committed plan.

    Strictly local apart from the one-time, anchor-serialised arming of
    peer plan markers and global coordinator payloads; idempotent, so a
    crash at any step is finished deterministically by the next writer on
    any involved path.
    """
    anchor = doc["anchor"]
    with _reorg_anchor_guard(anchor):
        anchor_fd = _reorg_anchor_flock(anchor)
        try:
            # Arm every peer's plan marker and publish the translated
            # coordinator records before any set changes shape.
            for peer in doc["involved"]:
                plan = _reorg_plan_path(peer)
                if not os.path.exists(plan):
                    freeze = _reorg_freeze_path(peer)
                    payload = json.dumps(doc, separators=(",", ":")).encode(
                        "utf-8"
                    )
                    tmp = plan + ".tmp"
                    try:
                        out = os.open(
                            tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666
                        )
                        try:
                            _write_bytes(out, payload)
                            os.fsync(out)
                        finally:
                            os.close(out)
                        os.replace(tmp, plan)
                    finally:
                        _unlink_if_exists(tmp)
                    _unlink_if_exists(freeze)
            for txid in doc.get("coords", ()):
                staged = os.path.join(
                    _tx_registry_dir(), f"{txid}{_REORG_COORD_TMP_SUFFIX}"
                )
                if os.path.exists(staged):
                    os.replace(staged, _tx_record_path(txid))

            section = doc["paths"][abspath]
            slice_path = abspath + _REORG_SEG_SUFFIX
            if os.path.exists(slice_path):
                # Publish the slice as the single numbered segment and
                # leave an empty live log, the same shape compaction
                # leaves.  The slice stays readable by name until the
                # rename, so a lock-free reader never sees a gap.
                for number in _segment_numbers(abspath):
                    _unlink_if_exists(f"{abspath}.{number}")
                _truncate_live_log(abspath)
                os.replace(slice_path, f"{abspath}.1")
            # Rebuilt prune basis: every destination starts at zero
            # pruned; moved records occupy ordinals from zero.
            _replace_marker(abspath, "0")
            _unlink_if_exists(abspath + _TRIM_SUFFIX)
            _unlink_if_exists(abspath + _TRIM_TMP_SUFFIX)

            # Snapshot registry and private copies.
            _reorg_remove_old_snapshots(abspath)
            snap_registry = abspath + _REORG_SNAP_REGISTRY_STAGED
            directory = os.path.dirname(abspath) or "."
            base = os.path.basename(abspath)
            handles = []
            if os.path.exists(snap_registry):
                try:
                    fd = os.open(snap_registry, os.O_RDONLY)
                    try:
                        raw = b""
                        while True:
                            chunk = os.read(fd, _READ_CHUNK)
                            if not chunk:
                                break
                            raw += chunk
                    finally:
                        os.close(fd)
                    handles = list(json.loads(raw.decode("utf-8")))
                except BaseException:
                    handles = []
            for name in list(os.listdir(directory)) if os.path.isdir(
                directory
            ) else []:
                if name.startswith(base + _REORG_SNAP_PREFIX):
                    handle = name[len(base) + len(_REORG_SNAP_PREFIX):]
                    os.replace(
                        os.path.join(directory, name),
                        os.path.join(
                            directory, base + _SNAP_COPY_SUFFIX + handle
                        ),
                    )
            if os.path.exists(snap_registry):
                os.replace(snap_registry, abspath + _REGISTRY_SUFFIX)
            _unlink_if_exists(snap_registry + ".tmp")

            # Consumer groups this set hosts after the move.
            hosted_groups = set(section.get("groups", ()))
            for group, state_path in list(_reorg_list_old_groups(abspath).items()):
                if group not in hosted_groups:
                    _unlink_if_exists(state_path)
            for name in list(os.listdir(directory)) if os.path.isdir(
                directory
            ) else []:
                if name.startswith(base + _REORG_GROUP_PREFIX):
                    group = name[len(base) + len(_REORG_GROUP_PREFIX):]
                    os.replace(
                        os.path.join(directory, name),
                        abspath + _GROUP_STATE_SUFFIX + group,
                    )

            # Transaction state: old sidecar/index/stages out, staged in.
            staged_sidecar = abspath + _REORG_TX_SIDECAR_STAGED
            staged_index = abspath + _REORG_TXINDEX_STAGED
            keep_stages = set(section.get("tx_stages", ()))
            _reorg_remove_old_tx_state(abspath, keep_stages)
            for name in list(os.listdir(directory)) if os.path.isdir(
                directory
            ) else []:
                if name.startswith(base + _REORG_TXSTAGE_PREFIX):
                    txid = name[len(base) + len(_REORG_TXSTAGE_PREFIX):]
                    os.replace(
                        os.path.join(directory, name),
                        _tx_stage_path(abspath, txid),
                    )
            if os.path.exists(staged_sidecar):
                os.replace(staged_sidecar, _tx_sidecar_path(abspath))
            _unlink_if_exists(staged_sidecar + ".tmp")
            if os.path.exists(staged_index):
                os.replace(staged_index, _tx_index_path(abspath))
            _unlink_if_exists(staged_index + ".tmp")

            # Audit chain: rebuilt where the layout still carries one,
            # removed everywhere else.
            if section.get("audit"):
                _unlink_if_exists(abspath + _AUDIT_SUFFIX)
                _unlink_if_exists(abspath + _AUDIT_TMP_SUFFIX)
                _sync_audit(abspath, strict=False)
            else:
                _unlink_if_exists(abspath + _AUDIT_SUFFIX)
                _unlink_if_exists(abspath + _AUDIT_TMP_SUFFIX)

            _unlink_if_exists(_reorg_plan_path(abspath))
            _unlink_if_exists(_reorg_freeze_path(abspath))
        finally:
            if anchor_fd is not None:
                os.close(anchor_fd)


def _finish_pending_reorg(path):
    """Finish a merge/split a crash interrupted on ``path`` (lock held).

    No-op without a committed plan marker.  A marker can only be observed
    while the run that published it is dead (it held this log's lock), so
    the anchor flock is free and taking it here cannot deadlock.
    """
    doc = _reorg_read_plan(path)
    if doc is None:
        # No committed plan: staging files and a freeze are pre-commit
        # orphans of a dead run; the anchor decides whether the run is in
        # fact gone before its coordinator temps are swept.
        freeze = _reorg_freeze_path(path)
        if not os.path.exists(freeze):
            _reorg_sweep_path_orphans(path)
            return
        involved = None
        anchor = path + _REORG_LOCK_SUFFIX
        fd = None
        try:
            if fcntl is not None:
                fd = os.open(anchor, os.O_RDWR | os.O_CREAT, 0o666)
                try:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                except OSError as exc:
                    if exc.errno in (
                        errno.EACCES, errno.EAGAIN, errno.EWOULDBLOCK
                    ):
                        # A live run still owns the anchor; its freeze is
                        # authoritative and the orphans are its staging.
                        return
                    raise
            _reorg_sweep_path_orphans(path)
            _reorg_sweep_coord_temps()
            for peer in [path]:
                _unlink_if_exists(_reorg_freeze_path(peer))
        finally:
            if fd is not None:
                os.close(fd)
        return
    _reorg_local_finalize(os.path.abspath(path), doc)


# -- coordinator translation ------------------------------------------------

def _reorg_translate_coordinator(record, context):
    """Rewrite one coordinator record for the new layout.

    ``context`` maps every involved old absolute path to a descriptor;
    other participating logs pass through untouched with their lines and
    write serial.  Returns ``(logs, records, serials)`` in canonical log
    order, with moved batches partitioned per new owner.
    """
    buckets = {}

    def add(owner, sortkey, lines, serial, moved):
        buckets.setdefault(
            owner, {"moved": [], "kept": None, "empty": None}
        )
        if moved == "lines":
            buckets[owner]["moved"].append((sortkey, lines))
        elif moved == "keep":
            buckets[owner]["kept"] = (lines, serial)
        else:  # empty participation on a moved log
            buckets[owner]["empty"] = sortkey

    for index, old in enumerate(record["logs"]):
        lines = record["records"][index]
        serial = record["serials"][index]
        descriptor = context.get(old)
        if descriptor is None:
            add(old, None, lines, serial, "keep")
            continue
        kind, data = descriptor
        if kind == "merge":
            dest, pruned, base, count = data
            if not lines:
                local = min(max(serial - pruned, 0), count)
                add(dest, base + local, [], base + local, "empty")
                continue
            for offset, line in enumerate(lines):
                local = min(max(serial + offset - pruned, 0), count)
                add(dest, base + local, line, None, "lines")
        else:
            points, pruned, count = data
            if not lines:
                local = min(max(serial - pruned, 0), count)
                owner = _reorg_point_owner(points, local)
                start = next(s for s, candidate in points if candidate == owner)
                add(owner, local, [], local - start, "empty")
                continue
            for offset, line in enumerate(lines):
                local = min(max(serial + offset - pruned, 0), count)
                owner = _reorg_point_owner(points, local)
                start = next(s for s, candidate in points if candidate == owner)
                add(owner, local, line, None, "lines")

    new_logs = []
    new_records = []
    new_serials = []
    for owner in sorted(buckets):
        bucket = buckets[owner]
        if bucket["kept"] is not None:
            lines, serial = bucket["kept"]
            new_logs.append(owner)
            new_records.append(list(lines))
            new_serials.append(serial)
            continue
        moved = sorted(bucket["moved"], key=lambda item: item[0])
        lines = [line for _sortkey, line in moved]
        if moved:
            serial = moved[0][0]
            descriptor = context_match = None
            for old, descriptor_value in context.items():
                kind, data = descriptor_value
                if kind == "merge" and data[0] == owner:
                    serial = moved[0][0]
                    break
                if kind == "split":
                    points = data[0]
                    for start, candidate in points:
                        if candidate == owner and start <= moved[0][0]:
                            serial = moved[0][0] - start
            new_logs.append(owner)
            new_records.append(lines)
            new_serials.append(serial)
        if not moved and bucket["empty"] is not None:
            new_logs.append(owner)
            new_records.append([])
            new_serials.append(bucket["empty"])
    return new_logs, new_records, new_serials

