# ---------------------------------------------------------------------------
# Online merge and split of independent metric log sets
#
# merge_metrics gathers several whole log sets, in the caller's deterministic
# order (destination first, then each source), into the destination set and
# leaves the sources empty; split_metrics moves every surviving record of
# one set into caller-named new sets at whole-record boundaries.  Records
# move byte for byte with their original newlines; the torn tail and blank
# lines keep the established read rule.  The new ordinal of every moved
# record is uniquely computable: merge lays the sets' surviving records out
# one after another, each set starting at the running record count; split
# lays the slices out in destination order.  Every destination rebuilds its
# pruned basis at zero, so the moved records are numbered from zero.
#
# Every involved log is guarded (the reentrant same-process guard) and
# flock-locked one at a time in lexicographic absolute-path order and held
# until the commit finishes, the same acyclic acquisition cross-log
# transactions use; concurrent appends, commits, rollbacks, adjudications
# and replays therefore serialise instead of deadlocking.  A freeze marker
# (``path.reorgfreeze``) is published on every involved path first; all
# content is then staged under reorg-private names.  The commit arms a full
# plan marker (``path.reorg``) on every involved path and replaces the
# affected coordinator records, and only afterwards does each path swap its
# own whole slice into place as its sole segment and install its translated
# private state.  Every step is local and idempotent:
#
# * a crash before arming leaves freezes and private staging files; the next
#   writer on a path waits on the anchor flock (the live run that could still
#   be staging holds this path's log lock, so it cannot be that run), then
#   sweeps the orphans and proceeds;
# * a crash at or after arming leaves at least one plan marker; the next
#   writer on any involved path re-arms every peer marker, publishes the
#   staged coordinator records and finishes each path it writes, so the
#   result is deterministically the new layout, never a mixture.
#
# Decided transactions keep their verdict; write serials, participating logs
# and staged batches are translated through the same one ordinal map the
# records use, partitioned across the new owner sets record by record.  A
# transaction still mid-preparation is never translated: it declared the old
# paths and finishes on them as an ordinary writer (merge leaves the sources
# as empty sets).  Snapshot handles are rebuilt against the moved sequence,
# consumer-group positions move through the same ordinal map, and the audit
# chain is rebuilt on the primary set(s).
#
# The per-log participant index (``path.txidx``) maintained here also scopes
# every read of the global transaction registry to transactions that actually
# touch the log in hand, so an unrelated corrupt coordinator record never
# disturbs an operation.
# ---------------------------------------------------------------------------

_REORG_VERSION = 1
_REORG_PLAN_SUFFIX = ".reorg"
_REORG_FREEZE_SUFFIX = ".reorgfreeze"
_REORG_LOCK_SUFFIX = ".reorglock"
_REORG_SEG_SUFFIX = ".reorgseg"
_REORG_SEG_TMP = _REORG_SEG_SUFFIX + ".tmp"
_REORG_SNAP_PREFIX = ".reorgsnap."
_REORG_SNAP_REGISTRY = ".reorg.snapshots"
_REORG_GROUP_PREFIX = ".reorggroup."
_REORG_TX_SIDECAR = ".reorg.tx"
_REORG_TXINDEX = ".reorg.txidx"
_REORG_TXSTAGE_PREFIX = ".reorgtxstage."
# Staged coordinator payloads live at "<id>.json.reorgtmp.<tag>"; the tag
# identifies the anchor set, so a crash sweep on one anchor never removes
# another live run's staging.
_REORG_COORD_TMP_MARK = ".json.reorgtmp."

_TX_INDEX_SUFFIX = ".txidx"
_TX_INDEX_TMP_SUFFIX = ".txidx.tmp"

# Reentrant same-process guards for the anchor flock, mirroring the
# transaction guards so same-process recovery never self-deadlocks.
_reorg_anchor_guards = {}
_reorg_anchor_guard_refs = {}


# -- per-log transaction participant index ---------------------------------

def _tx_index_path(path):
    return path + _TX_INDEX_SUFFIX


def _tx_read_index(path):
    """Return the participant-id index, or ``None`` when no index exists."""
    try:
        fd = os.open(_tx_index_path(path), os.O_RDONLY)
    except FileNotFoundError:
        return None
    try:
        raw = b""
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            raw += chunk
    finally:
        os.close(fd)
    try:
        ids = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise ValueError(
            f"corrupt transaction index {_tx_index_path(path)!r}: {exc}"
        ) from exc
    if not isinstance(ids, list) or any(
        isinstance(txid, bool) or not isinstance(txid, int) or txid < 0
        for txid in ids
    ):
        raise ValueError(
            f"corrupt transaction index {_tx_index_path(path)!r}: "
            f"index must be a list of non-negative integer transaction ids"
        )
    return sorted(ids)


def _tx_write_index(path, ids):
    """Atomically publish the participant index; an empty one is removed."""
    tmp = path + _TX_INDEX_TMP_SUFFIX
    if not ids:
        _unlink_if_exists(tmp)
        _unlink_if_exists(_tx_index_path(path))
        return
    payload = json.dumps(sorted(set(ids)), separators=(",", ":")).encode(
        "utf-8"
    )
    _tx_publish_json(tmp, _tx_index_path(path), payload)


def _tx_index_add(path, txid):
    """Append one identifier to a log's participant index (lock held)."""
    ids = _tx_read_index(path)
    if ids is None:
        ids = []
    if txid not in ids:
        _tx_write_index(path, ids + [txid])


def _tx_related_records(abspaths):
    """Yield coordinator records related to any of ``abspaths``.

    The narrow read scope: when every log carries a participant index only
    the indexed identifiers are opened, so an unrelated corrupt record
    never affects the operation; a log without an index falls back to a
    registry scan filtered by participation.
    """
    union = set()
    indexed = True
    for abspath in abspaths:
        ids = _tx_read_index(abspath)
        if ids is None:
            indexed = False
            break
        union.update(ids)
    if indexed:
        for txid in sorted(union):
            record = _tx_read_coordinator(txid)
            if record is not None:
                yield record
        return
    wanted = set(abspaths)
    for record in _tx_registry_records():
        if not wanted.isdisjoint(record["logs"]):
            yield record


# -- markers, locks and orphan cleanup -------------------------------------

def _reorg_plan_path(path):
    return path + _REORG_PLAN_SUFFIX


def _reorg_freeze_path(path):
    return path + _REORG_FREEZE_SUFFIX


def _reorg_anchor_tag(anchor):
    return hashlib.blake2b(
        anchor.encode("utf-8"), digest_size=8
    ).hexdigest()


def _reorg_lock_path(abspath):
    return abspath + _REORG_LOCK_SUFFIX


def _reorg_anchor_guard(anchor):
    return _TxGuard(_reorg_anchor_guards, _reorg_anchor_guard_refs, anchor)


def _reorg_read_json_marker(target):
    try:
        fd = os.open(target, os.O_RDONLY)
    except FileNotFoundError:
        return None
    try:
        raw = b""
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            raw += chunk
    finally:
        os.close(fd)
    try:
        return json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise ValueError(f"corrupt reorg state {target!r}: {exc}") from exc


def _reorg_publish(target, payload_bytes):
    _tx_publish_json(target + ".tmp", target, payload_bytes)


def _reorg_publish_json(target, state):
    _reorg_publish(target, json.dumps(state, separators=(",", ":")).encode(
        "utf-8"
    ))


def _reorg_flock(anchor, blocking):
    if fcntl is None:
        return None
    fd = os.open(anchor, os.O_RDWR | os.O_CREAT, 0o666)
    flags = fcntl.LOCK_EX if blocking else fcntl.LOCK_EX | fcntl.LOCK_NB
    try:
        try:
            fcntl.flock(fd, flags)
        except OSError as exc:
            if not blocking and exc.errno in (
                errno.EACCES, errno.EAGAIN, errno.EWOULDBLOCK
            ):
                os.close(fd)
                return False
            os.close(fd)
            raise
    except OSError:
        raise
    return fd


def _reorg_sweep_private(path):
    """Remove this path's private reorg staging files (write lock held).

    Safe without any plan knowledge: a live reorganisation holds this
    path's log lock for its whole staging window, so finding these files
    while this writer holds the lock means the run that made them is dead.
    """
    directory = os.path.dirname(path) or "."
    base = os.path.basename(path)
    exact = (
        _REORG_SEG_SUFFIX,
        _REORG_SEG_TMP,
        _REORG_SNAP_REGISTRY,
        _REORG_SNAP_REGISTRY + ".tmp",
        _REORG_TX_SIDECAR,
        _REORG_TX_SIDECAR + ".tmp",
        _REORG_TXINDEX,
        _REORG_TXINDEX + ".tmp",
        _REORG_PLAN_SUFFIX,
        _REORG_PLAN_SUFFIX + ".tmp",
        _REORG_FREEZE_SUFFIX,
        _REORG_FREEZE_SUFFIX + ".tmp",
    )
    prefixes = (
        _REORG_SNAP_PREFIX,
        _REORG_GROUP_PREFIX,
        _REORG_TXSTAGE_PREFIX,
    )
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return
    for name in names:
        if name in (base + suffix for suffix in exact) or any(
            name.startswith(base + prefix) for prefix in prefixes
        ):
            _unlink_if_exists(os.path.join(directory, name))


def _reorg_sweep_coord_temps(tag):
    """Remove staged coordinator payloads carrying one dead anchor's tag."""
    directory = _tx_registry_dir()
    suffix = _REORG_COORD_TMP_MARK + tag
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return
    for name in names:
        if _REORG_COORD_TMP_MARK in name and name.endswith(suffix):
            _unlink_if_exists(os.path.join(directory, name))


def _reorg_list_group_files(path):
    """``{group: state_path}`` of consumer-group state files on one log."""
    directory = os.path.dirname(path) or "."
    base = os.path.basename(path)
    prefix = base + _GROUP_STATE_SUFFIX
    groups = {}
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        return groups
    for name in names:
        if not name.startswith(prefix):
            continue
        group = name[len(prefix):]
        if group.endswith(_GROUP_STATE_LOCK_SUFFIX) or group.endswith(
            _GROUP_STATE_TMP_SUFFIX
        ):
            continue
        groups[group] = os.path.join(directory, name)
    return groups


def _reorg_point_owner(points, local):
    """Owner of local surviving ordinal over sorted ``[(start, owner)]``.

    A local ordinal equal to a slice start belongs to that slice; one at or
    past the last start (the end boundary) belongs to the last slice.
    """
    owner = points[0][1]
    for start, candidate in points:
        if local < start:
            return owner
        owner = candidate
    return owner


# -- validation and locking ------------------------------------------------

def _reorg_check_str_path(path):
    if not isinstance(path, str):
        raise OSError(
            f"log path must be a string, got {type(path).__name__}"
        )
    if os.path.isdir(path):
        raise IsADirectoryError(f"log path is a directory: {path!r}")


def _reorg_require_existing(path):
    _reorg_check_str_path(path)
    if not os.path.exists(path) and not _segment_numbers(path):
        raise FileNotFoundError(f"metrics log does not exist: {path!r}")


def _reorg_check_no_path_prefix_collision(absolute):
    """Reject paths whose sidecar name spaces overlap.

    Sidecars are named ``path.<suffix>``; two involved paths where one is a
    dotted prefix of the other (e.g. ``a`` and ``a.b``) could make one's
    members or staging files match the other's prefixes.
    """
    ordered = sorted(absolute)
    for first, second in zip(ordered, ordered[1:]):
        if second == first or second.startswith(first + ".") or (
            os.sep != "/" and second.startswith(first + "/")
        ):
            raise ValueError(
                f"log paths share a sidecar name space: {first!r}, {second!r}"
            )


def _reorg_lock_one(abspath, create):
    """Guard and lock one involved log, settling it (create sets born)."""
    guard = _tx_log_guard(abspath)
    guard.__enter__()
    try:
        if create:
            fd = _mutation_lock(abspath, create=True)
        else:
            fd = _tx_lock_existing_set(abspath)
            _finish_pending(abspath)
            fd = _relock_after_settle(fd, abspath, create=True)
        return guard, fd
    except BaseException:
        guard.__exit__(None, None, None)
        raise


def _reorg_acquire(involved, creates=()):
    """Guard, lock and settle involved logs in lexicographic order."""
    creates = set(creates)
    held = []
    try:
        for abspath in sorted(involved):
            guard, fd = _reorg_lock_one(abspath, abspath in creates)
            held.append([abspath, guard, fd])
        return held
    except BaseException:
        for _abspath, guard, fd in reversed(held):
            if fd is not None:
                try:
                    os.close(fd)
                except OSError:
                    pass
            guard.__exit__(None, None, None)
        raise


def _reorg_release(held):
    for _abspath, guard, fd in reversed(held):
        if fd is not None:
            os.close(fd)
        guard.__exit__(None, None, None)


# -- streaming staging -----------------------------------------------------

def _reorg_path_record_stream(path):
    """Yield every surviving record's bytes across one set's members."""
    for member in _segment_members(path):
        yield from _iter_raw_records(member)


def _reorg_collect(path):
    """Settled ``(pruned, surviving, total)`` for one log."""
    pruned = _read_prune_state(path)[0]
    surviving = 0
    for member in _segment_members(path):
        surviving += sum(1 for _ in _iter_raw_records(member))
    return pruned, surviving, pruned + surviving


def _reorg_stage_slice(target, streams):
    """Stream record byte streams into ``<target>.reorgseg`` atomically."""
    tmp = target + _REORG_SEG_TMP
    out = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    try:
        for stream in streams:
            for raw in stream:
                _write_bytes(out, raw)
        os.fsync(out)
    finally:
        os.close(out)
    os.replace(tmp, target + _REORG_SEG_SUFFIX)


def _reorg_stage_copy(src, dst):
    """Stream one file byte for byte into a staged name and fsync it."""
    tmp = dst + ".tmp"
    out = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    try:
        fd = os.open(src, os.O_RDONLY)
        try:
            while True:
                chunk = os.read(fd, _READ_CHUNK)
                if not chunk:
                    break
                _write_bytes(out, chunk)
        finally:
            os.close(fd)
        os.fsync(out)
    finally:
        os.close(out)
    os.replace(tmp, dst)


def _reorg_window(stream, start, end):
    """Yield surviving records with local index in ``[start, end)``."""
    index = 0
    for raw in stream:
        if start <= index < end:
            yield raw
        index += 1


# -- per-path finalisation -------------------------------------------------

def _reorg_listdir(directory):
    try:
        return os.listdir(directory)
    except FileNotFoundError:
        return []


def _reorg_install_renames(abspath, doc):
    """Move this path's staged snapshot copies, group files and tx stages."""
    directory = os.path.dirname(abspath) or "."
    base = os.path.basename(abspath)
    for name in _reorg_listdir(directory):
        if name.startswith(base + _REORG_SNAP_PREFIX):
            handle = name[len(base) + len(_REORG_SNAP_PREFIX):]
            os.replace(
                os.path.join(directory, name),
                os.path.join(directory, base + _SNAP_COPY_SUFFIX + handle),
            )
        elif name.startswith(base + _REORG_GROUP_PREFIX):
            group = name[len(base) + len(_REORG_GROUP_PREFIX):]
            os.replace(
                os.path.join(directory, name),
                abspath + _GROUP_STATE_SUFFIX + group,
            )
        elif name.startswith(base + _REORG_TXSTAGE_PREFIX):
            txid = name[len(base) + len(_REORG_TXSTAGE_PREFIX):]
            os.replace(
                os.path.join(directory, name),
                _tx_stage_path(abspath, txid),
            )


def _reorg_remove_old_private(abspath, hosted_groups):
    """Remove the snapshot/group/tx private state the reorg replaces."""
    directory = os.path.dirname(abspath) or "."
    base = os.path.basename(abspath)
    # Snapshots: old registry and every private copy are replaced wholesale.
    for name in _reorg_listdir(directory):
        if name.startswith(base + _SNAP_COPY_SUFFIX):
            _unlink_if_exists(os.path.join(directory, name))
    _unlink_if_exists(abspath + _REGISTRY_SUFFIX)
    _unlink_if_exists(abspath + _REGISTRY_TMP_SUFFIX)
    # Groups: anything not hosted on this set after the move is removed.
    for group, state_path in _reorg_list_group_files(abspath).items():
        if group not in hosted_groups:
            _unlink_if_exists(state_path)
    # Transaction live sidecar, index and stages are replaced by staged ones.
    for name in _reorg_listdir(directory):
        if name.startswith(base + _TX_STAGE_SUFFIX) or name.startswith(
            base + _TX_STAGE_TMP_SUFFIX
        ):
            _unlink_if_exists(os.path.join(directory, name))
    _unlink_if_exists(_tx_sidecar_path(abspath))
    _unlink_if_exists(abspath + _TX_SIDECAR_TMP_SUFFIX)
    _unlink_if_exists(_tx_index_path(abspath))
    _unlink_if_exists(abspath + _TX_INDEX_TMP_SUFFIX)


def _reorg_arm_everything(doc):
    """Publish peer plan markers and coordinator records (idempotent)."""
    payload = json.dumps(doc, separators=(",", ":")).encode("utf-8")
    for peer in doc["involved"]:
        plan = _reorg_plan_path(peer)
        if not os.path.exists(plan):
            _reorg_publish(plan, payload)
        _unlink_if_exists(_reorg_freeze_path(peer))
    for txid, tmp_name in doc.get("coords", ()):
        staged = os.path.join(_tx_registry_dir(), tmp_name)
        if os.path.exists(staged):
            os.replace(staged, _tx_record_path(txid))


def _reorg_finalize_path(abspath, doc):
    """Swap one path into its new layout from the committed plan."""
    section = doc["paths"][abspath]
    slice_path = abspath + _REORG_SEG_SUFFIX
    if os.path.exists(slice_path):
        for number in _segment_numbers(abspath):
            _unlink_if_exists(f"{abspath}.{number}")
        _truncate_live_log(abspath)
        os.replace(slice_path, f"{abspath}.1")
    # The moved records are numbered from zero on every destination.
    _replace_marker(abspath, "0")
    _unlink_if_exists(abspath + _TRIM_SUFFIX)
    _unlink_if_exists(abspath + _TRIM_TMP_SUFFIX)

    hosted_groups = set(section.get("groups", ()))
    _reorg_remove_old_private(abspath, hosted_groups)
    _reorg_install_renames(abspath, doc)
    snap_registry = abspath + _REORG_SNAP_REGISTRY
    if os.path.exists(snap_registry):
        os.replace(snap_registry, abspath + _REGISTRY_SUFFIX)
    _unlink_if_exists(snap_registry + ".tmp")
    staged_sidecar = abspath + _REORG_TX_SIDECAR
    if os.path.exists(staged_sidecar):
        os.replace(staged_sidecar, _tx_sidecar_path(abspath))
    _unlink_if_exists(staged_sidecar + ".tmp")
    staged_index = abspath + _REORG_TXINDEX
    if os.path.exists(staged_index):
        os.replace(staged_index, _tx_index_path(abspath))
    _unlink_if_exists(staged_index + ".tmp")

    if section.get("audit"):
        _unlink_if_exists(abspath + _AUDIT_SUFFIX)
        _unlink_if_exists(abspath + _AUDIT_TMP_SUFFIX)
        _sync_audit(abspath, strict=False)
    else:
        _unlink_if_exists(abspath + _AUDIT_SUFFIX)
        _unlink_if_exists(abspath + _AUDIT_TMP_SUFFIX)
    _unlink_if_exists(_reorg_plan_path(abspath))
    _unlink_if_exists(_reorg_freeze_path(abspath))


def _finish_pending_reorg(path):
    """Settle a merge/split a crash interrupted (live-log lock held).

    A committed plan marker is finished to the new layout; a freeze without
    a plan is pre-commit residue and is swept once the anchor flock proves
    the staging run is gone; with neither marker the path's private staging
    files are plain orphans.
    """
    abspath = os.path.abspath(path)
    plan = _reorg_read_json_marker(_reorg_plan_path(path))
    freeze = _reorg_read_json_marker(_reorg_freeze_path(path))
    if plan is None and freeze is None:
        _reorg_sweep_private(path)
        return
    if plan is None:
        anchor = freeze["anchor"]
        tag = freeze["tag"]
        with _reorg_anchor_guard(anchor):
            fd = _reorg_flock(anchor, blocking=True)
            try:
                plan = _reorg_read_json_marker(_reorg_plan_path(path))
                if plan is not None:
                    _reorg_arm_everything(plan)
                    _reorg_finalize_path(abspath, plan)
                    return
                _reorg_sweep_private(path)
                _reorg_sweep_coord_temps(tag)
                _unlink_if_exists(_reorg_freeze_path(path))
            finally:
                if fd is not None:
                    os.close(fd)
        return
    anchor = plan["anchor"]
    with _reorg_anchor_guard(anchor):
        fd = _reorg_flock(anchor, blocking=True)
        try:
            _reorg_arm_everything(plan)
            _reorg_finalize_path(abspath, plan)
        finally:
            if fd is not None:
                os.close(fd)


# -- coordinator translation ------------------------------------------------

def _reorg_translate(record, maps):
    """Rewrite one coordinator record for the new layout.

    ``maps`` maps each involved old absolute path to
    ``(points, pruned)`` where ``points`` is the sorted
    ``[(slice-start local ordinal, new owner absolute path)]`` table the
    record moves through; merge gives one point at zero for the
    destination, split gives one point per destination.  Logs not present
    in ``maps`` keep their lines and write serial untouched.  Returns
    ``(logs, records, serials)`` in canonical (sorted owner) order.
    """
    buckets = {}

    def bucket(owner):
        return buckets.setdefault(
            owner, {"kept": None, "moved": [], "empty": None}
        )

    for index, old in enumerate(record["logs"]):
        lines = record["records"][index]
        serial = record["serials"][index]
        mapping = maps.get(old)
        if mapping is None:
            bucket(old)["kept"] = (list(lines), serial)
            continue
        points, pruned = mapping
        if not lines:
            # A zero-record participation still names a set through the
            # boundary its recorded serial pins.
            local = serial - pruned
            owner = _reorg_point_owner(points, local)
            start = next(s for s, candidate in points if candidate == owner)
            bucket(owner)["empty"] = local - start
            continue
        for offset, line in enumerate(lines):
            local = serial + offset - pruned
            owner = _reorg_point_owner(points, local)
            start = next(s for s, candidate in points if candidate == owner)
            bucket(owner)["moved"].append((local - start, local, line))

    new_logs = []
    new_records = []
    new_serials = []
    for owner in sorted(buckets):
        entry = buckets[owner]
        if entry["kept"] is not None:
            lines, serial = entry["kept"]
            new_logs.append(owner)
            new_records.append(lines)
            new_serials.append(serial)
            continue
        moved = sorted(entry["moved"], key=lambda item: item[1])
        if moved:
            new_logs.append(owner)
            new_records.append([line for _new_ord, _local, line in moved])
            new_serials.append(moved[0][0])
        elif entry["empty"] is not None:
            new_logs.append(owner)
            new_records.append([])
            new_serials.append(entry["empty"])
    return new_logs, new_records, new_serials

