def _reorg_drain_prepares(involved):
    """Wait for in-flight begins to finish staging, holding no log lock.

    Freeze markers are already published when this runs, so no new begin
    can enter staging (the begin entry gate blocks before it creates
    anything); only begins that started earlier remain, and they finish
    on their own because this waits without taking their log locks.  A
    dead begin's acquirable flock needs no wait -- the per-log settle run
    under the log locks sweeps its residue.
    """
    if fcntl is None:
        return
    while True:
        busy = [
            record["id"]
            for record in _tx_related_records(involved)
            if record["s"] == _TX_STATUS_PREPARING
            and _reorg_prepare_busy(record["id"])
        ]
        if not busy:
            return
        time.sleep(0.01)

