    """Finish a committed reorg from one involved path (log lock held).

    Arm every missing peer plan marker first, finalise every peer one at
    a time -- never two peer log locks at once -- then publish the
    translated coordinator records and retire the markers.  The current
    path's lock is already held, so it is finalised directly.
    """
    abspath = os.path.abspath(path)
    plan_payload = json.dumps(doc, separators=(",", ":")).encode("utf-8")
    for peer in doc["involved"]:
        plan = _reorg_plan_path(peer)
        if not os.path.exists(plan):
