import json
import os
import shutil
import subprocess
import sys
import tempfile
import threading

sys.path.insert(0, "/mnt/c/claude_gsb/cla04/solverA/task026")
from weighted_batcher import (
    append_metrics, merge_metrics, split_metrics, recover_metrics,
    tx_begin_metrics, tx_commit_metrics, tx_read_metrics,
)

ROOT = tempfile.mkdtemp(prefix="reorg_conc_")
errors = []


def p(n):
    return os.path.join(ROOT, n)


# --- Test 1: concurrent appends while merges happen ---
logs = [p(f"m{i}") for i in range(4)]
for lg in logs:
    for i in range(5):
        append_metrics(lg, json.dumps({"i": i}))


def appender(lg, stop_at, tag):
    n = 100
    try:
        for i in range(n):
            append_metrics(lg, json.dumps({tag: i}))
    except Exception as exc:
        errors.append(f"appender {tag}: {exc!r}")
    stop_at.set()


stop = threading.Event()
threads = []
for idx, lg in enumerate(logs):
    t = threading.Thread(target=appender, args=(lg, stop, f"t{idx}"))
    threads.append(t)

# merger repeatedly merges logs[1..] into logs[0], then splits out
def reorganizer():
    try:
        for _ in range(3):
            merge_metrics(logs)
            # split destination into itself + a temp, then merge back
            tmp = p("reorgtmp")
            count = len(recover_metrics(logs[0]))
            half = count // 2
            split_metrics(logs[0], [logs[0], tmp], [0, half])
            merge_metrics([logs[0], tmp])
    except Exception as exc:
        errors.append(f"reorganizer: {exc!r}")


for t in threads:
    t.start()
rt = threading.Thread(target=reorganizer)
rt.start()
for t in threads:
    t.join(timeout=30)
rt.join(timeout=30)
alive = [t for t in threads if t.is_alive()] + ([rt] if rt.is_alive() else [])
if alive:
    print("DEADLOCK: threads still alive")
    sys.exit(1)

# every record is still recoverable; no torn/duplicated content
rows = recover_metrics(logs[0])
print("final dest rows:", len(rows))
# sources empty
for lg in logs[1:]:
    assert recover_metrics(lg) == [], lg
assert not os.path.exists(p("reorgtmp")) or recover_metrics(p("reorgtmp")) == []

# --- Test 2: concurrent tx commits with merges ---
tlogs = [p(f"tx{i}") for i in range(2)]
for lg in tlogs:
    for i in range(3):
        append_metrics(lg, json.dumps({"base": i}))


def tx_worker(tag):
    try:
        for i in range(10):
            txid = tx_begin_metrics(tlogs, [[{tag: i}], [{"z": i}]])
            tx_commit_metrics(txid)
    except Exception as exc:
        errors.append(f"tx {tag}: {exc!r}")


def merger2():
    try:
        for _ in range(3):
            merge_metrics(tlogs)
            tmp = p("txtmp")
            count = len(recover_metrics(tlogs[0]))
            split_metrics(tlogs[0], [tlogs[0], tmp], [0, count])
            # both empties; merge back
            merge_metrics([tlogs[0], tmp])
    except Exception as exc:
        errors.append(f"merger2: {exc!r}")


workers = [threading.Thread(target=tx_worker, args=(f"w{i}",)) for i in range(3)]
m = threading.Thread(target=merger2)
for w in workers:
    w.start()
m.start()
for w in workers:
    w.join(timeout=30)
m.join(timeout=30)
alive = [w for w in workers if w.is_alive()] + ([m] if m.is_alive() else [])
if alive:
    print("DEADLOCK in tx test")
    sys.exit(1)

final = recover_metrics(tlogs[0])
print("final tx rows:", len(final))
# every committed batch present exactly once
zcount = sum(1 for r in final if "z" in r)
print("z records:", zcount)

if errors:
    print("ERRORS:")
    for e in errors:
        print(" ", e)
    sys.exit(1)
print("CONCURRENCY OK")
shutil.rmtree(ROOT, ignore_errors=True)

