            raise
    return fd


def _mutation_lock(path, create):
    """Lock the segment set for a mutation, or just prove the log exists.

    Returns the live-log lock fd on POSIX (caller closes it) or ``None``
    on platforms without :mod:`fcntl`, where the existence check has
    already closed its descriptor and no rename may happen with a handle
    still open.

    Before the log lock is taken, a caller that holds no higher-level
    reorganisation or transaction lock finishes or waits out any
    merge/split marker covering the log, anchor first; callers inside a
    transaction or reorganisation skip that step (their lock order is
    anchor -> coordinator -> log, and they wait on the live
    reorganisation's flocks directly).
    """
    if (
        not _reorg_prepare_is_active()
        and not _reorg_live_is_active()
        and not _tx_coord_is_active()
        and (
            os.path.exists(path + _REORG_FREEZE_SUFFIX)
            or os.path.exists(path + _REORG_PLAN_SUFFIX)
        )
    ):
        _reorg_recover_markers(path)
    fd = _open_locked(path, create)
    if fcntl is None:
        os.close(fd)
        return None
    return fd

